public:
    bool canAliceWin(vector<string>& a, vector<string>& b) {
        int i = 1, j = 0, k = 1;
        string w = a[0];
        while (true) {
            if (k) {
                if (j == b.size()) return true;
                if ((b[j][0] == w[0] && b[j] > w) || b[j][0] - w[0] == 1) {
                    w = b[j];
                    k ^= 1;
                }
                j++;
            } else {
                if (i == a.size()) return false;
                if ((a[i][0] == w[0] && a[i] > w) || a[i][0] - w[0] == 1) {
                    w = a[i];
                    k ^= 1;
                }
                i++;
            }
        }
    }
};

class Solution {
    public boolean canAliceWin(String[] a, String[] b) {
        int i = 1, j = 0;
        boolean k = true;
        String w = a[0];
        while (true) {
            if (k) {
                if (j == b.length) return true;
                if ((b[j].charAt(0) == w.charAt(0) && b[j].compareTo(w) > 0) || b[j].charAt(0) - w.charAt(0) == 1) {
                    w = b[j];
                    k = !k;
                }
                j++;
            } else {
                if (i == a.length) return false;
                if ((a[i].charAt(0) == w.charAt(0) && a[i].compareTo(w) > 0) || a[i].charAt(0) - w.charAt(0) == 1) {
                    w = a[i];
                    k = !k;
                }
                i++;
            }
        }
    }
}

